// Extract application data from root level fields
const applicantData = {
  "Applicant Name": $input.item.json["Applicant Name"],
  "Product Name": $input.item.json["Product Name"],
  "Alcohol%": $input.item.json["Alcohol%"],
  "Bottled By": $input.item.json["Bottled By"],
  "Certification": $input.item.json["Certification"],
  "Application ID": $input.item.json["Application ID"],
  "App Rec Id": $input.item.json["App Rec Id"]
};

// Vision API response is in the visionApiResponse field
const visionResponse = $input.item.json.visionApiResponse;

// Extract label JSON from Vision API
const extractedText = visionResponse.choices?.[0]?.message?.content || '';
let labelData = {};

try {
  const jsonMatch = extractedText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    labelData = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  labelData = { raw: extractedText };
}

// Mapping between application fields and label fields
const fieldMapping = {
  'Applicant Name': 'applicantName',
  'Product Name': 'productName',
  'Alcohol%': 'alcoholPercentage',
  'Bottled By': 'bottledBy',
  'Certification': 'certification'
};

const mismatches = [];
let validationStatus = 'Pass';

// Compare each field
for (const [appField, labelField] of Object.entries(fieldMapping)) {
  const appValue = applicantData[appField];
  const labelValue = labelData[labelField];

  const normalizedAppValue = String(appValue || '').trim().toLowerCase();
  const normalizedLabelValue = String(labelValue || '').trim().toLowerCase();

  if (normalizedAppValue === 'none' || normalizedAppValue === '') {
    if (normalizedLabelValue && normalizedLabelValue !== 'null' && normalizedLabelValue !== 'none' && normalizedLabelValue !== '') {
      mismatches.push({
        field: appField,
        applicationValue: appValue || 'None',
        labelValue: labelValue,
        reason: 'Application shows None/empty but label has value'
      });
      validationStatus = 'Fail';
    }
  } else {
    if (!normalizedLabelValue || normalizedLabelValue === 'null' || normalizedLabelValue === 'none') {
      mismatches.push({
        field: appField,
        applicationValue: appValue,
        labelValue: labelValue || 'Not found',
        reason: 'Label missing value that exists in application'
      });
      validationStatus = 'Fail';
    } else if (normalizedAppValue !== normalizedLabelValue) {
      mismatches.push({
        field: appField,
        applicationValue: appValue,
        labelValue: labelValue,
        reason: 'Values do not match exactly'
      });
      validationStatus = 'Fail';
    }
  }
}

// Return final validation result
return {
  json: {
    'Application ID': applicantData['Application ID'],
    'App Rec Id': applicantData['App Rec Id'],
    validationStatus,
    mismatchCount: mismatches.length,
    mismatchedFields: mismatches.map(m => m.field).join(', '),
    mismatchDetails: mismatches.map(m => `${m.field}: App='${m.applicationValue}' vs Label='${m.labelValue}'`).join(' | '),
    extractedData: labelData
  }
};

const imageBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Image = imageBuffer.toString('base64');

// Preserve all original application data fields
const originalData = $input.item.json;

return {
  json: {
    ...originalData,
    requestBody: {
      model: 'gpt-4o',
      messages: [{
        role: 'user',
        content: [
          {
            type: 'text',
            text: 'You are analyzing an alcohol beverage label. Extract and return ONLY the following specific information in JSON format: {"applicantName": "exact company/brand name", "productName": "exact product name", "alcoholPercentage": "exact alcohol % or ABV value", "bottledBy": "exact bottling company/location", "certification": "any certification text, or null if none visible"}. Be precise and extract exactly what you see on the label.'
          },
          {
            type: 'image_url',
            image_url: {
              url: `data:image/jpeg;base64,${base64Image}`
            }
          }
        ]
      }],
      max_tokens: 1000
    }
  }
};

// Get the current item's index
const currentIndex = $item(0).$itemIndex;

// Get the application data from Prepare Vision API Request node using the same index
const applicationData = $('Prepare Vision API Request').all()[currentIndex].json;

// Get the Vision API response from current item
const visionResponse = $input.item.json;

// Extract the relevant application fields (excluding requestBody)
const { requestBody, ...relevantApplicationData } = applicationData;

// Merge application data with Vision API response
return {
  json: {
    ...relevantApplicationData,
    visionApiResponse: visionResponse
  }
};
